import {providerModels} from './model-options.js';
import {providerPanel,handleProviderChange,handleModelListInput,collectProviders,updatePanel,collectUpdateSettings} from './settings-ui.js';
import { markZoomableImages, openImageViewer, imageViewerOpen } from './image-viewer.js';
import { attachMentions } from './mentions.js';
const paths = {
  plus:'M12 5v14M5 12h14', check:'m5 12 4 4L19 6', arrow:'M5 12h14m-5-5 5 5-5 5', chevron:'m9 5 7 7-7 7',
  image:'M4 4h16v16H4zM4 16l5-5 4 4 3-3 4 4M8 8h.01', film:'M4 4h16v16H4zM8 4v16M16 4v16M4 8h4M4 16h4M16 8h4M16 16h4',
  play:'m9 5 11 7-11 7z', edit:'m15 5 4 4M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15z',
  refresh:'M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-1l2 3M4 15l2 3a7 7 0 0 0 12-1',
  upload:'M12 16V3m-5 5 5-5 5 5M4 16v4h16v-4', download:'M12 3v13m-5-5 5 5 5-5M4 16v4h16v-4',
  settings:'m10 3-1 3-3 1-3 3 2 2v3l2 3 3-1 2 2 3-1 1-3 3-1 1-3-2-2V7l-3-2-3 1zM9 12a3 3 0 1 0 6 0 3 3 0 0 0-6 0',
  close:'m6 6 12 12M6 18 18 6', log:'M8 6h12M8 12h12M8 18h12M3 6h.01M3 12h.01M3 18h.01',
  clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0', copy:'M9 9h12v12H9zM15 5V2H2v13h3',
  sparkle:'m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6z', folder:'M3 6h6l2 2h10v12H3z',
  alert:'m12 3 10 17H2zM12 9v4M12 16h.01', save:'M5 3h13l3 3v15H3V3zM7 3v6h10V3M7 21v-7h10v7',
};
const icon = (name, size=17, extra='') => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" class="${extra}"><path d="${paths[name]||paths.film}"/></svg>`;
const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const active = job => job && ['pending','submitting','queued','running','downloading'].includes(job.state);
const kindLabel = { character:'人物', scene:'场景', prop:'道具', frame:'分镜图' };
const jobLabel = job => ({idle:'待生成',pending:'等待开始',submitting:'正在提交',queued:'排队中',running:'生成中',downloading:'下载中',completed:'已完成',failed:'待处理',unknown:'待核对'}[job?.state]||'待生成');
const state = { providerProfiles:null,updates:null, projects:[], settings:{}, capabilities:null, concurrency:{images:{limit:10,running:0,queued:0},videos:{limit:10,running:0,queued:0}}, videoProfile:null, prompts:{definitions:[],overrides:{},outputContract:''}, project:null, token:'', rules:{}, filter:'all', selected:new Set(), selectedAssets:new Set(), knownAssets:new Set(), knownShots:new Set(), draft:null, dirty:false, modal:null, busy:false, disconnected:false };
let motionRequested=false, viewTransition=null, modalClosing=null;
let uploadAssetId=null, toastTimer, lastProjectJSON='', polling=false, switching=false;

async function api(path, options={}) {
  const init={method:options.method||'GET',headers:{}};
  if(init.method!=='GET'){init.headers={'Content-Type':'application/json','X-Workflow-Token':state.token};init.body=JSON.stringify(options.body||{});}
  const response=await fetch(path,init);
  const result=await response.json();
  if(!response.ok)throw new Error(result.error||'操作失败');
  return result;
}
function notify(message,error=false){const box=document.querySelector('#toast');box.textContent=message;box.className=`visible${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.className='',error?6500:3500);}
function draftFrom(project){return {title:project.title,script:project.script,style:project.style,aspectRatio:project.aspectRatio,ruleNotes:project.ruleNotes,clipDuration:project.clipDuration,resolution:project.resolution,skipReview:project.skipReview===true};}
function profile(){return state.project?.videoProfile||state.videoProfile;}
function durationOptions(value){const p=profile();if(p.unavailable)return `<option value="${Number(value)}">${Number(value)} 秒（参数待获取）</option>`;const values=Array.from({length:p.maxDuration-p.minDuration+1},(_,i)=>p.minDuration+i);if(!values.includes(Number(value)))values.unshift(Number(value));return values.map(n=>`<option value="${n}" ${Number(value)===n?'selected':''}>${n} 秒${n<p.minDuration||n>p.maxDuration?'（需调整）':''}</option>`).join('');}
function resolutionOptions(value){const values=[...profile().resolutions];if(!values.includes(value))values.unshift(value);return values.map(n=>`<option value="${escape(n)}" ${value===n?'selected':''}>${escape(n)}${profile().resolutions.includes(n)?'':'（需调整）'}</option>`).join('');}
function projectUrl(project,file){return `/media/${project.id}/${encodeURIComponent(file)}`;}
function setProject(project,{reset=false}={}){const currentShotIds=new Set(project.shots.map(s=>s.id));state.selected=new Set([...state.selected].filter(id=>currentShotIds.has(id)));if(reset){state.selectedAssets=new Set();state.knownAssets=new Set();state.knownShots=new Set();}for(const asset of project.assets){if(!state.knownAssets.has(asset.id)){state.knownAssets.add(asset.id);if(asset.selected!==false)state.selectedAssets.add(asset.id);}}for(const shot of project.shots){if(!state.knownShots.has(shot.id)){state.knownShots.add(shot.id);if(!shot.video&&!active(shot.job))state.selected.add(shot.id);}}state.concurrency=project.concurrency||state.concurrency;state.project=project;lastProjectJSON=JSON.stringify(project);if(reset||!state.dirty)state.draft=draftFrom(project);if(reset){state.dirty=false;state.filter='all';state.selected=new Set(project.shots.filter(shot=>!shot.video).map(shot=>shot.id));window.scrollTo(0,0);}render();}
async function refreshProjects(){state.projects=await api('/api/projects');}
async function loadProject(id){switching=true;try{const project=await api(`/api/projects/${id}`);localStorage.setItem('drama-project',id);setProject(project,{reset:true});}finally{switching=false;}}
function badge(job){const mode=job?.state==='completed'?'success':active(job)?'running':['failed','unknown'].includes(job?.state)?'failed':'';return `<span class="badge ${mode}">${active(job)?icon('refresh',11,'spin'):job?.state==='completed'?icon('check',11):''}${jobLabel(job)}</span>`;}

function sidebar(){return `<aside class="sidebar"><div class="brand"><span class="brand-mark">镜</span><div><div class="brand-name">镜序</div><div class="brand-caption">短剧工作台</div></div></div><button class="new-project" data-action="new">${icon('plus',17)}<span>新建项目</span></button><div class="sidebar-label">我的项目 <span class="tiny">${state.projects.length.toString().padStart(2,'0')}</span></div><nav class="project-list" aria-label="项目列表">${state.projects.map(project=>`<button class="project-link ${project.id===state.project?.id?'active':''}" data-action="project" data-id="${project.id}" title="${escape(project.title)}">${project.thumbnail?`<img class="project-thumb" src="${projectUrl(project,project.thumbnail)}" alt="">`:`<span class="project-thumb">${icon('film',17)}</span>`}<span class="project-item-text"><span class="project-title">${escape(project.title)}</span><span class="project-meta">${project.shotCount?`${project.shotCount} 个分镜`:'新项目'} · ${project.assetCount} 项素材</span></span>${active(project.preparation)?'<span class="dot pulse"></span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="ghost" data-action="settings" title="接口设置">${icon('settings',17)}<span>接口设置</span></button><button class="ghost" data-action="logs" title="任务记录">${icon('log',17)}<span>任务记录</span></button><div class="local-label"><span class="dot"></span>资料保存在本机</div></div></aside>`;}

function stepper(project){const hasAssets=project.assets.length>0,ready=project.assets.some(asset=>asset.selected!==false)&&project.assets.filter(asset=>asset.selected!==false).every(asset=>asset.image),hasShots=project.shots.length>0,done=hasShots&&project.shots.every(shot=>shot.video);return `<nav class="stepper" aria-label="制作流程"><a href="#script-section" class="step ${project.script?'done':'current'}"><span class="step-number">${project.script?icon('check',12):'01'}</span>输入剧本</a><span class="step-line"></span><a href="#assets-section" class="step ${ready?'done':hasAssets?'current':''}"><span class="step-number">${ready?icon('check',12):'02'}</span>生成资产</a><span class="step-line"></span><a href="#storyboard-section" class="step ${hasShots?'done':ready?'current':''}"><span class="step-number">${hasShots?icon('check',12):'03'}</span>确认分镜</a><span class="step-line"></span><a href="#storyboard-section" class="step ${done?'done':hasShots?'current':''}"><span class="step-number">${done?icon('check',12):'04'}</span>生成视频</a></nav>`;}

function progressStrip(project){const preparing=project.preparation;if(!active(preparing)&&preparing.state!=='failed'&&!state.disconnected)return '';const failed=preparing.state==='failed';const count=preparing.total?`${preparing.completed||0} / ${preparing.total}`:'';return `<div class="progress-strip ${failed?'error':''}"><div class="progress-icon">${icon(failed?'alert':'refresh',20,failed?'':'spin')}</div><div class="progress-content"><strong>${state.disconnected?'暂时无法连接后台':failed?'有任务需要处理':escape(preparing.stage)}</strong><p>${state.disconnected?'请确认本地后台仍在运行，连接恢复后会继续更新。':failed?escape(preparing.error):`${count?`${preparing.phase==='analysis'?'段落分析':preparing.phase==='reparse-storyboards'?'分段解析':'资产完成'} ${count}　·　`:''}你可以离开当前页面，后台会继续处理。`}</p>${active(preparing)&&preparing.total?`<div class="progress-track"><span style="width:${Math.round(100*(preparing.completed||0)/preparing.total)}%"></span></div>`:''}</div><button class="text-button" data-action="logs">查看记录 ${icon('chevron',12)}</button></div>`;}

function reviewSwitch(project){return `<div class="review-mode"><label><span>跳过人工检查</span><input id="skip-review" type="checkbox" role="switch" aria-label="跳过人工检查" ${state.draft.skipReview?'checked':''}></label><p>${state.draft.skipReview?'已开启：点击开始后，自动衔接资产图、全部分镜和视频，按服务商计费。关闭可停止后续自动提交。':'默认关闭：资产清单和全部分镜分别停下来，等你修改、勾选后再生成。'}</p></div>`;}
function scriptSection(project){const d=state.draft,preparing=active(project.preparation);return `<section class="section-card" id="script-section"><div class="section-top"><div><div class="section-title"><span class="section-num">01</span><h2>剧本与制作设置</h2></div><p class="section-subtitle">${d.skipReview?'全自动：拆解后生成资产图、全部分镜和视频。':'粘贴完整剧本，先拆解并列清单；此步不生成图片或视频。'}</p></div><button class="small ghost" data-action="save-project" ${!state.dirty?'disabled':''}>${icon('save',14)}<span>${state.dirty?'保存修改':'已保存'}</span></button></div><div class="script-body"><div class="script-editor"><textarea id="script-input" data-draft="script" aria-label="剧本内容" placeholder="在这里粘贴你的剧本…&#10;&#10;可以包含场次、人物、动作与对白，系统会根据内容提取需要的素材。" ${preparing?'disabled':''}>${escape(d.script)}</textarea><div class="editor-bottom"><span>${d.script.length.toLocaleString()} 字</span><span>${state.dirty?'有未保存的修改':'剧本与制作进度保存在本机'}</span></div></div><div class="script-settings">${reviewSwitch(project)}<label class="field"><span>画面风格</span><select id="style-input" data-draft="style" ${preparing?'disabled':''}>${['写实电影','国风写实','日系动画','3D动画','水彩插画','漫画'].map(style=>`<option ${d.style===style?'selected':''}>${style}</option>`).join('')}</select></label><div class="settings-pair"><label class="field"><span>画面比例</span><select id="ratio-input" data-draft="aspectRatio" ${preparing?'disabled':''}>${['16:9','9:16','1:1'].map(ratio=>`<option ${d.aspectRatio===ratio?'selected':''}>${ratio}</option>`).join('')}</select></label><label class="field"><span>每段时长</span><select aria-label="每段时长" data-draft="clipDuration" ${preparing?'disabled':''}>${durationOptions(d.clipDuration)}</select></label></div><label class="field"><span>视频分辨率</span><select data-draft="resolution" ${preparing?'disabled':''}>${resolutionOptions(d.resolution)}</select></label><label class="field"><span>补充制作规则 <span class="muted">（可选）</span></span><textarea id="rules-input" class="rule-input" data-draft="ruleNotes" placeholder="例如：人物服装保持统一，场景使用暖色光线。" ${preparing?'disabled':''}>${escape(d.ruleNotes)}</textarea></label></div></div><div class="prepare-action"><div class="prepare-help">${project.sourceChanged?'<strong>剧本已修改</strong> · 重新准备时将另建版本，保留已有素材。':preparing?'正在后台处理，进度会逐段保存。':d.skipReview?'全自动开启：点击开始后，依次生成资产图、分镜与视频。':'先列资产清单，<strong>由你选择需要生成的图片</strong>。'}</div><button class="primary" data-action="prepare" ${preparing||state.busy||(!project.sourceChanged&&!d.skipReview&&project.chunks?.every(chunk=>chunk.analysisState==='completed'))?'disabled':''}>${icon(preparing?'refresh':'sparkle',16,preparing?'spin':'')}<span>${preparing?'正在准备…':project.preparation.state==='failed'?'继续拆解资产清单':project.sourceChanged?'按修改准备新版本':d.skipReview?'开始全自动生成':project.chunks?.every(chunk=>chunk.analysisState==='completed')?'资产清单已列出':'拆解剧本并列资产清单'}</span></button></div></section>`;}

function assetCard(asset){const working=active(asset.job);return `<article class="asset-card ${asset.kind}" data-asset="${asset.id}"><div class="asset-visual">${asset.image?`<img src="${asset.image.url}" alt="${escape(asset.name)}" loading="lazy">`:`<div class="asset-placeholder">${icon(working?'refresh':'image',27,working?'spin':'')}<span>${working?jobLabel(asset.job):'等待生成图片'}</span></div>`}<span class="asset-type">${kindLabel[asset.kind]||'素材'}</span>${working?`<span class="asset-generation">${jobLabel(asset.job)}${asset.job.progress?` · ${asset.job.progress}%`:''}</span>`:''}<span class="asset-status" title="${jobLabel(asset.job)}">${icon(working?'refresh':asset.job?.state==='failed'?'alert':asset.image?'check':'clock',12,working?'spin':'')}</span></div><div class="asset-info"><label class="asset-choice"><input type="checkbox" data-asset-select="${asset.id}" aria-label="选择资产 ${escape(asset.name)}" ${state.selectedAssets.has(asset.id)?'checked':''} ${active(state.project.preparation)?'disabled':''}><h3>${escape(asset.name)}</h3></label><p class="asset-description">${escape(asset.description||'点击编辑，调整素材描述和生图提示词')}</p></div>${asset.job?.error?`<p class="asset-error">${escape(asset.job.error)}</p>`:''}<div class="asset-tools"><button class="text-button" data-action="edit-asset" data-id="${asset.id}" ${working?'disabled':''}>${icon('edit',13)}<span>编辑</span></button><div class="row" style="gap:0">${asset.job?.taskId&&['failed','unknown'].includes(asset.job.state)?`<button data-action="resume-asset" data-id="${asset.id}" title="继续查询原任务">${icon('clock',13)}</button>`:''}<button data-action="upload-asset" data-id="${asset.id}" title="替换图片" ${working?'disabled':''}>${icon('upload',13)}<span>替换</span></button><button data-action="regenerate-asset" data-id="${asset.id}" title="重新生成图片" ${working?'disabled':''}>${icon('refresh',13)}<span>重做</span></button></div></div></article>`;}

function assetsSection(project){const visible=state.filter==='all'?project.assets:project.assets.filter(asset=>asset.kind===state.filter);return `<section class="assets-section" id="assets-section"><div class="section-heading"><div><h2>资产清单与图片 <span class="count">${project.assets.length.toString().padStart(2,'0')}</span></h2><p>先勾选需要的资产；可编辑描述和提示词，再生成所选或全部图片。</p></div><div class="row asset-heading-controls"><label class="image-model-control"><span>生图模型</span><select data-image-model-select aria-label="生图模型">${providerModels({...state.settings.grsai,service:'grsai'}).map(m=>`<option value="${escape(m.id)}" ${m.id===state.settings.grsai.model?'selected':''}>${escape(m.label)}</option>`).join('')}</select></label><div class="filter-tabs" aria-label="素材类别">${[['all','全部'],['character','人物'],['scene','场景'],['prop','道具'],...(project.assets.some(asset=>asset.kind==='frame')?[['frame','分镜图']]:[])].map(([kind,label])=>`<button class="filter-tab ${state.filter===kind?'active':''}" data-action="filter" data-kind="${kind}">${label}</button>`).join('')}</div></div></div>${project.assets.length?`<div class="asset-batch"><label><input type="checkbox" id="select-all-assets" ${project.assets.every(asset=>state.selectedAssets.has(asset.id))?'checked':''} ${active(project.preparation)?'disabled':''}>全选资产</label><span class="muted small-text">已选 ${state.selectedAssets.size} / ${project.assets.length} 项 · 已有图片直接复用</span><div class="row"><button data-action="generate-selected-assets" ${!state.selectedAssets.size||active(project.preparation)?'disabled':''}>生成所选 (${state.selectedAssets.size})</button><button class="primary" data-action="generate-all-assets" ${active(project.preparation)?'disabled':''}>一键全部生成</button></div></div>`:''}${visible.length?`<div class="asset-grid">${visible.map(assetCard).join('')}</div>`:`<div class="empty-panel">${icon('image',28)}<strong>${project.assets.length?'这个分类还没有素材':'资产将在这里逐一出现'}</strong><p>${project.assets.length?'切换“全部”查看其他素材。':'输入剧本并点击拆解，先列出清单，由你勾选后再生成。'}</p></div>`}</section>`;}

function shotCard(project,shot,index){const refs=shot.assetIds.map(id=>project.assets.find(asset=>asset.id===id)).filter(Boolean);const thumbnail=refs.find(asset=>asset.kind==='frame'&&asset.image)||refs.find(asset=>asset.kind==='scene'&&asset.image)||refs.find(asset=>asset.image);return `<article class="shot-card" data-shot="${shot.id}"><div class="shot-header"><div class="shot-title"><input type="checkbox" aria-label="选择分镜 ${index+1}" data-shot-select="${shot.id}" ${state.selected.has(shot.id)?'checked':''} ${active(shot.job)||active(shot.rebuildJob)?'disabled':''}><span class="shot-index">${String(index+1).padStart(2,'0')}</span><h3>${escape(shot.title)}</h3></div>${active(shot.rebuildJob)?badge(shot.rebuildJob):shot.continuityReview?.state==='required'?'<span class="badge failed">待检查衔接</span>':shot.stale?'<span class="badge running">需要重新确认</span>':badge(shot.job)}</div><div class="shot-body"><div class="shot-preview">${thumbnail?`<img src="${thumbnail.image.url}" alt="${escape(shot.title)}参考画面">`:`<div class="asset-placeholder" style="height:100%">${icon('film',25)}</div>`}${shot.video?`<button data-action="play" data-id="${shot.id}" aria-label="播放${escape(shot.title)}"><span class="preview-play"><span>${icon('play',16)}</span></span></button><span class="shot-video-tag">已生成 · ${shot.video.duration} 秒</span>`:'<span class="shot-video-tag">参考画面</span>'}</div><div><div class="shot-meta"><label class="shot-duration-control"><span>时长</span><select aria-label="${escape(shot.title)}时长" data-shot-duration="${shot.id}" ${active(shot.job)||active(shot.rebuildJob)?'disabled':''}>${durationOptions(shot.duration)}</select></label>${shot.chunkTitle?`<span>${escape(shot.chunkTitle)}</span>`:''}<span>${project.aspectRatio}</span><span>${escape(project.style)}</span></div><p class="prompt-preview">${escape(shot.prompt)}</p><div class="reference-chips">${refs.map(asset=>`<span class="ref-chip">${asset.image?`<img src="${asset.image.url}" alt="">`:''}@${escape(asset.name)}</span>`).join('')}</div></div></div><div class="shot-actions"><span class="job-message ${shot.job?.error?'error':''}">${active(shot.job)?icon('refresh',12,'spin'):shot.video?icon('check',12):icon('clock',12)}${escape(shot.rebuildJob?.error||shot.rebuildJob?.message||shot.compatibilityError||shot.job?.error||shot.job?.message||(shot.video?'视频已下载至本机':'等待你确认提示词与参考图'))}${active(shot.job)&&shot.job.progress?` · ${shot.job.progress}%`:''}</span><div class="row">${shot.video?`<a href="${shot.video.url}" download="${escape(project.title)}_${index+1}.mp4">${icon('download',13)}下载</a>`:''}${shot.continuityReview?.state==='required'?`<button data-action="confirm-continuity" data-id="${shot.id}" title="请先核对本镜与前后分镜，确认剧情、台词、站位、道具和编号连续" ${active(project.preparation)?'disabled':''}>已核对，确认衔接</button>`:''}<button data-action="edit-shot" data-id="${shot.id}" ${active(shot.job)||active(shot.rebuildJob)?'disabled':''}>${icon('edit',13)}编辑提示词</button><button data-action="rebuild-shot" data-id="${shot.id}" ${active(shot.job)||active(shot.rebuildJob)?'disabled':''}>${icon('refresh',13)}重新拆分分镜</button>${shot.job?.taskId&&shot.job.state==='failed'?`<button data-action="resume-video" data-id="${shot.id}">${icon('clock',13)}继续查询</button>`:''}<button class="${shot.video?'':'dark'}" data-action="review-shot" data-id="${shot.id}" ${active(shot.job)||active(shot.rebuildJob)?'disabled':''}>${icon('play',12)}${shot.video?'重新生成':project.skipReview?'开始生成':'审阅并生成'}</button></div></div></article>`;}

function continuityNotice(project){const n=project.shots.filter(s=>s.continuityReview?.state==='required').length;return n?`<div class="hint-box continuity-notice"><div><strong>${n} 条后续分镜需检查衔接</strong><p>前序内容已变化。可全部重新解析分镜，或逐条核对后点击“确认衔接”。未处理的条目暂不提交视频。</p></div><button data-action="reparse-storyboards" ${active(project.preparation)?'disabled':''}>全部重新解析分镜</button></div>`:'';}
function reparseNotice(project){const r=project.storyboardReparse;if(!r||r.state==='completed')return '';return `<div class="hint-box reparse-notice"><div><strong>${r.state==='running'?'正在全部重新解析分镜':'全部解析未完成，旧分镜已保留'}</strong><p>已完成 ${r.completed} / ${r.total} 段 · 新草稿 ${r.generated} 条。${r.error?escape(r.error):'全部完成后统一替换；已有资产图与旧成片会保留。'}</p></div>${r.canResume?'<button data-action="resume-reparse-storyboards">继续全部解析</button>':''}</div>`;}
function reparseStoryboardsDialog(){const p=state.project,r=p.videoProfile;const duration=p.clipDuration>=r.minDuration&&p.clipDuration<=r.maxDuration?p.clipDuration:r.defaultDuration;openModal({title:'全部重新解析分镜',subtitle:'根据整份原剧本重新拆分，按顺序衔接所有段落。',wide:true,body:`<div class="hint-box">当前 ${p.shots.length} 条分镜将重新解析。已有资产图直接复用，只调用文字模型；全部成功后统一替换。旧分镜、成片和历史记录保留，失败可继续，不会自动生成图片或视频。</div><label class="field"><span>统一每段时长</span><select id="reparse-duration">${durationOptions(duration)}</select></label><label class="field" style="margin-top:18px"><span>本次调整要求（可选）</span><textarea id="reparse-notes" placeholder="填写本轮分镜拆解的调整要求" maxlength="6000"></textarea></label><p class="muted small-text">使用设置中当前保存的分镜拆解与输出格式规则。完成后全部分镜列在本页底部，等你检查再生成视频。</p>`,footer:'<button data-action="close-modal">取消</button><button class="primary" data-action="confirm-reparse-storyboards">开始全部重新解析</button>'});}
function deliveryNotice(project){const d=project.delivery;if(!d||(!d.localQueued&&!d.remotePending))return '';return `<div class="hint-box delivery-status">${d.localQueued?`还有 ${d.localQueued} 条视频尚未提交，请保持电脑与后台运行。`:''}${d.remotePending?` ${d.remotePending} 条已有服务端任务编号；下次启动工作台会继续查询状态并下载成片。`:''}<br>服务商成片下载地址有效期有限，完成后请尽早启动工作台接收。</div>`;}
function storyboardsSection(project){const selected=project.shots.filter(shot=>state.selected.has(shot.id));return `<section class="storyboard-section" id="storyboard-section"><div class="section-heading"><div><h2>分镜与视频 <span class="count">${project.shots.length.toString().padStart(2,'0')}</span></h2><p>${escape(project.videoProfile.model)} · ${escape(project.resolution)} · ${project.videoProfile.minDuration}–${project.videoProfile.maxDuration} 秒。${project.videoProfile.onShelf===false?'服务端当前标记为未上架。':''}检查动作、运镜与素材引用，再决定开始生成。</p></div><div class="row"><button class="small reparse-all-button" data-action="reparse-storyboards" ${!project.assets.length||active(project.preparation)||active(project.mergeJob)||project.shots.some(s=>active(s.job)||active(s.rebuildJob))?'disabled':''}>${icon('refresh',13)}全部重新解析分镜</button><span class="badge">${project.shots.filter(shot=>shot.video&&!shot.stale).length} / ${project.shots.length} 已生成</span>${project.mergedVideo&&!project.mergedVideo.stale?`<button class="small" data-action="play-merged">${icon('play',12)}查看整集</button>`:''}${project.shots.length?`<button class="small" data-action="merge" ${project.shots.some(shot=>!shot.video||shot.stale||active(shot.job))||active(project.mergeJob)?'disabled':''}>${icon(active(project.mergeJob)?'refresh':'film',13,active(project.mergeJob)?'spin':'')}${active(project.mergeJob)?'正在合成':'合成整集'}</button>`:''}</div></div>${reparseNotice(project)}${continuityNotice(project)}${deliveryNotice(project)}${project.mergeJob?.error?`<div class="hint-box" style="color:var(--red)">${escape(project.mergeJob.error)}</div>`:active(project.mergeJob)?`<div class="hint-box">${escape(project.mergeJob.message)}</div>`:''}${project.shots.length?`${project.shots.map((shot,index)=>shotCard(project,shot,index)).join('')}<div class="selection-footer"><div class="row"><label class="select-all"><input type="checkbox" id="select-all" aria-label="全选分镜" ${project.shots.every(shot=>state.selected.has(shot.id))?'checked':''}>全选</label><div><strong>已选择 ${selected.length} 个分镜 <span class="muted">· ${selected.reduce((total,shot)=>total+shot.duration,0)} 秒</span></strong><p>${project.skipReview?'已跳过人工检查，点击后直接生成所选分镜。':'生成前会再次展示提示词和本次引用的素材。'}</p></div></div><button class="primary" data-action="review-selected" ${!selected.length||active(project.preparation)?'disabled':''}>${icon('play',14)}${project.skipReview?'开始生成所选':'确认并开始生成'} ${selected.length?`(${selected.length})`:''}</button></div>`:`<div class="empty-panel">${icon('film',29)}<strong>分镜提示词将在资产准备完成后生成</strong><p>每条分镜都可以单独修改、选择参考图并查看生成进度。</p></div>`}</section>`;}

function syncSelections(){
 const p=state.project;if(!p)return;
 document.querySelectorAll('[data-asset-select]').forEach(node=>node.checked=state.selectedAssets.has(node.dataset.assetSelect));
 const allAssets=document.querySelector('#select-all-assets');if(allAssets){allAssets.checked=p.assets.length>0&&p.assets.every(a=>state.selectedAssets.has(a.id));allAssets.indeterminate=state.selectedAssets.size>0&&!allAssets.checked;}
 const assetCount=document.querySelector('.asset-batch>.muted');if(assetCount)assetCount.textContent=`已选 ${state.selectedAssets.size} / ${p.assets.length} 项 · 已有图片直接复用`;
 const assetButton=document.querySelector('[data-action="generate-selected-assets"]');if(assetButton){assetButton.textContent=`生成所选 (${state.selectedAssets.size})`;assetButton.disabled=!state.selectedAssets.size||active(p.preparation);}
 document.querySelectorAll('[data-shot-select]').forEach(node=>node.checked=state.selected.has(node.dataset.shotSelect));
 const allShots=document.querySelector('#select-all');if(allShots){allShots.checked=p.shots.length>0&&p.shots.every(shot=>state.selected.has(shot.id));allShots.indeterminate=state.selected.size>0&&!allShots.checked;}
 const selected=p.shots.filter(shot=>state.selected.has(shot.id)),count=document.querySelector('.selection-footer strong');
 if(count)count.innerHTML=`已选择 ${selected.length} 个分镜 <span class="muted">· ${selected.reduce((n,shot)=>n+shot.duration,0)} 秒</span>`;
 const videoButton=document.querySelector('[data-action="review-selected"]');if(videoButton){videoButton.innerHTML=`${icon('play',14)}${p.skipReview?'开始生成所选':'确认并开始生成'} ${selected.length?`(${selected.length})`:''}`;videoButton.disabled=!selected.length||active(p.preparation);}
}
function reducedMotion(){return matchMedia('(prefers-reduced-motion: reduce)').matches;}
function render(){motionRequested=false;renderContent();}
function slidePanels(root){root?.animate([{opacity:.35,transform:'translateY(7px)'},{opacity:1,transform:'translateY(0)'}],{duration:230,easing:'cubic-bezier(.2,.8,.2,1)'});}
function movePill(nav){if(!nav||reducedMotion())return;let pill=nav.querySelector('.sliding-pill');if(!pill){pill=document.createElement('i');pill.className='sliding-pill';nav.prepend(pill);}const item=nav.querySelector('button.active');if(!item)return;const box=nav.getBoundingClientRect(),r=item.getBoundingClientRect();pill.style.width=`${r.width}px`;pill.style.height=`${r.height}px`;pill.style.transform=`translate(${r.left-box.left+nav.scrollLeft}px,${r.top-box.top+nav.scrollTop}px)`;}
function renderContent(){const focused=document.activeElement?.id,selection=document.activeElement instanceof HTMLTextAreaElement?[document.activeElement.selectionStart,document.activeElement.selectionEnd]:null,scroll=window.scrollY;const project=state.project;document.querySelector('#app').innerHTML=`<div class="app-shell">${sidebar()}<main class="main-shell"><header class="topbar"><div class="breadcrumb"><span>我的工作区</span>${icon('chevron',11)}<strong>短剧制作</strong></div><button class="small concurrency-trigger" data-action="concurrency" title="设置图片与视频并发数">${icon('settings',14)}<span>并发设置</span><span class="concurrency-mini">图 ${state.concurrency.images.limit} · 视频 ${state.concurrency.videos.limit}</span></button><div class="service-status"><span class="dot ${state.disconnected?'pulse':''}"></span>${state.disconnected?'连接恢复中':'本地工作台'}</div></header><div class="workspace">${project?`<div class="project-heading"><div><div class="eyebrow">制作工作区</div><h1>${escape(project.title)}</h1><p class="description">编辑剧本、检查素材，确认分镜后再生成视频。</p></div><div class="heading-tools">${project.demoImported?'<span class="badge success">真实生成示例</span>':''}<button class="icon-button ghost" data-action="rename" title="修改项目名称">${icon('edit',16)}</button><button class="icon-button ghost" data-action="duplicate" title="复制为新项目">${icon('copy',16)}</button><button class="icon-button ghost" data-action="logs" title="查看任务记录">${icon('log',17)}</button></div></div>${stepper(project)}${progressStrip(project)}${scriptSection(project)}${chunksSection(project)}${assetsSection(project)}${storyboardsSection(project)}`:`<div class="welcome"><div class="welcome-inner"><div class="welcome-mark">${icon('film',31)}</div><h1>从一段剧本，<br>开始你的下一幕。</h1><p>整理人物、场景与道具，生成分镜，<br>把想法一步步变成属于你的短剧。</p><button class="primary" data-action="new">${icon('plus',16)}创建第一个项目</button></div></div>`}</div></main></div>`;
if(focused){const target=document.getElementById(focused);if(target){target.focus({preventScroll:true});if(selection&&target instanceof HTMLTextAreaElement)target.setSelectionRange(...selection);}}window.scrollTo({top:scroll,behavior:'instant'});markZoomableImages(document.querySelector('#app'));syncSelections();}

function openModal({title,subtitle='',body,footer='',wide=false,review=false,onReady}){if(modalClosing){clearTimeout(modalClosing);modalClosing=null;}state.modal={title};document.querySelector('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''} ${review?'review-modal':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><div><h2 id="modal-title">${escape(title)}</h2>${subtitle?`<p>${escape(subtitle)}</p>`:''}</div><button class="icon-button ghost" data-action="close-modal" aria-label="关闭">${icon('close',18)}</button></header><div class="modal-body">${body}<p class="modal-error" id="modal-error" role="alert"></p></div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;markZoomableImages(document.querySelector('#modal-root'));onReady?.();requestAnimationFrame(()=>{document.querySelectorAll('.settings-tabs,.prompt-nav,.filter-tabs').forEach(movePill);});const first=document.querySelector('.modal input:not([type=hidden]),.modal textarea,.modal button');first?.focus({preventScroll:true});}
function closeModal(){if(state.modal?.submitting)return;state.modal=null;const root=document.querySelector('#modal-root');if(reducedMotion()){root.innerHTML='';return;}root.querySelector('.modal-overlay')?.classList.add('is-closing');modalClosing=setTimeout(()=>{root.innerHTML='';modalClosing=null;},170);}
function modalError(error){const box=document.querySelector('#modal-error');if(box)box.textContent=error.message;else notify(error.message,true);}
function modalBusy(busy){if(state.modal)state.modal.submitting=busy;document.querySelectorAll('.modal-footer button').forEach(button=>button.disabled=busy);}

function openNew(){openModal({title:'新建短剧项目',subtitle:'给故事一个名字，随后粘贴剧本开始制作。',body:'<label class="field"><span>项目名称</span><input id="new-title" placeholder="剧本名称" maxlength="80" autocomplete="off"></label>',footer:'<button data-action="close-modal">取消</button><button class="primary" data-action="create-project">创建项目</button>'});}
function editAsset(id){const asset=state.project.assets.find(item=>item.id===id);openModal({title:`编辑${kindLabel[asset.kind]||'素材'}`,subtitle:'修改提示词后，可以只重做这一张图片。',wide:true,body:`<div class="edit-grid"><div class="edit-image">${asset.image?`<img src="${asset.image.url}" alt="${escape(asset.name)}">`:`${icon('image',40)}`}</div><div class="edit-fields"><label class="field"><span>素材名称 · 用于自动引用</span><input id="asset-name" value="${escape(asset.name)}" maxlength="60"></label><label class="field"><span>设定说明</span><textarea id="asset-description" class="description-input">${escape(asset.description)}</textarea></label><label class="field"><span>生图提示词</span><textarea id="asset-prompt">${escape(asset.prompt)}</textarea></label></div></div>${asset.kind==='character'?`<details class="hint-box character-rule"><summary>固定人物生图规则 · 16:9 面部＋三视图（自动附加）</summary><pre>${escape(state.rules.characterSheet||'单张16:9，最左面部特写，右侧正面、90°侧面、背面三视图。')}</pre></details>`:''}`,footer:`<span class="footnote">替换或重做图片后，相关视频将标记为需要重新确认。</span><button data-action="save-asset" data-id="${id}">保存修改</button><button class="primary" data-action="save-regenerate-asset" data-id="${id}">${icon('refresh',14)}保存并重新生图</button>`});state.modal.assetId=id;}
function editShot(id){const shot=state.project.shots.find(item=>item.id===id);openModal({title:'编辑分镜提示词',subtitle:'输入 @ 选择素材；点击下方缩略图只放大预览。',wide:true,body:`<label class="field"><span>分镜名称</span><input id="shot-title" value="${escape(shot.title)}" maxlength="80"></label><label class="field" style="margin-top:18px"><span>本镜时长（可随时修改）</span><select id="shot-duration">${durationOptions(shot.duration)}</select></label><label class="field mention-field" style="margin-top:18px"><span>视频提示词 · 输入 @ 选择图片</span><textarea id="shot-prompt" class="large-prompt">${escape(shot.prompt)}</textarea></label><div class="reference-picker">${state.project.assets.filter(asset=>asset.image).map(asset=>`<button type="button" data-action="preview-reference" data-id="${asset.id}" aria-label="预览${escape(asset.name)}"><img src="${asset.image.url}" alt="${escape(asset.name)}">${escape(asset.name)}</button>`).join('')}</div><div class="hint-box">缩略图只用于看图。在提示词里输入 @，选择素材后插入引用。修改时长后可手动调整时间线，也可用AI重新拆分，让动作与对白匹配新时长。</div>`,footer:`<button data-action="rebuild-shot" data-id="${id}">${icon('refresh',14)}重新拆分分镜</button><button data-action="close-modal">取消</button><button class="primary" data-action="save-shot" data-id="${id}">保存分镜</button>`,onReady:()=>attachMentions(document.querySelector('#shot-prompt'),state.project.assets.filter(asset=>asset.image))});state.modal.shotId=id;}
function rebuildShotDialog(id){const shot=state.project.shots.find(item=>item.id===id),editing=state.modal?.shotId===id;
 const draft={title:editing?document.querySelector('#shot-title').value:shot.title,prompt:editing?document.querySelector('#shot-prompt').value:shot.prompt,duration:editing?Number(document.querySelector('#shot-duration').value):shot.duration};
 openModal({title:'AI重新拆分分镜',subtitle:'只重新处理这一条的动作和对白；可拆成一条或多条，原图片与视频会保留。',wide:true,body:`<label class="field"><span>每条片段时长</span><select id="rebuild-duration">${durationOptions(draft.duration)}</select></label><label class="field" style="margin-top:18px"><span>需要重新拆分的内容</span><textarea id="rebuild-prompt" class="large-prompt">${escape(draft.prompt)}</textarea></label><label class="field" style="margin-top:18px"><span>修改要求（可选）</span><textarea id="rebuild-notes" placeholder="填写你希望调整的动作、节奏或运镜"></textarea></label><p class="hint-box">锁定原分镜的起点和终点，重拆后将后续条目标记为待对齐，可全部重新解析分镜，或逐条人工核对确认。失败保留原分镜，不自动提交视频。</p>`,footer:`<button data-action="close-modal">取消</button><button class="primary" data-action="confirm-rebuild-shot" data-id="${id}">开始AI重新拆分</button>`});state.modal.rebuildDraft=draft;}


async function openReview(ids){if(state.dirty)await saveProject();if(state.project.skipReview){setProject(await api(`/api/projects/${state.project.id}/videos`,{method:'POST',body:{shotIds:ids,skipReview:true}}));state.selected.clear();notify('已跳过人工检查，所选视频已加入生成队列');return;}const review=await api(`/api/projects/${state.project.id}/review`,{method:'POST',body:{shotIds:ids}});openModal({title:'生成前确认',subtitle:'请检查本次的提示词和参考素材，点击下方按钮才会提交视频任务。',review:true,wide:true,body:`<div class="review-summary"><div><strong>${review.shots.length} 个分镜 · 共 ${review.totalSeconds} 秒</strong><p>${escape(review.shots[0].model)} · ${review.shots[0].resolution} · ${review.shots[0].aspectRatio} · 各镜时长见下方</p></div><span class="badge running">待你确认</span></div>${review.shots.map((shot,index)=>`<section class="review-shot"><h3>${String(index+1).padStart(2,'0')}　${escape(shot.title)} · ${shot.duration} 秒</h3><p class="review-label">本次引用的 ${shot.assets.length} 张素材</p><div class="review-refs">${shot.assets.map(asset=>`<div class="review-ref"><img src="${asset.url}" alt="${escape(asset.name)}"><p>${escape(asset.name)}</p></div>`).join('')}</div><p class="review-label">将提交的完整提示词</p><div class="review-prompt">${escape(shot.prompt)}</div></section>`).join('')}`,footer:`<span class="footnote">仅提交本次确认的内容，已有成片会保留。</span><button data-action="close-modal">返回修改</button><button class="primary" id="confirm-generate" data-action="confirm-video">${icon('play',14)}开始生成 ${review.shots.length} 段视频</button>`});state.modal.review=review;}

function concurrencyControl(key,title,detail){const current=state.concurrency[key];return `<section class="concurrency-control"><div class="concurrency-heading"><div><h3>${title}</h3><p>${detail}</p></div><span class="badge">正在处理 ${current.running} · 排队 ${current.queued}</span></div><div class="concurrency-stepper"><button data-action="concurrency-step" data-key="${key}" data-step="-1" aria-label="减少${title}">−</button><input id="concurrency-${key}" data-concurrency-number="${key}" type="number" min="1" max="50" step="1" value="${current.limit}" aria-label="${title}"><button data-action="concurrency-step" data-key="${key}" data-step="1" aria-label="增加${title}">＋</button><span>条同时进行</span></div><input class="concurrency-slider" data-concurrency-range="${key}" type="range" min="1" max="50" value="${current.limit}" aria-label="${title}滑块"><div class="concurrency-presets">${[1,5,10,20,30,50].map(n=>`<button data-action="concurrency-preset" data-key="${key}" data-value="${n}">${n}</button>`).join('')}</div></section>`;}
async function openConcurrency(){state.concurrency=await api('/api/concurrency');openModal({title:'并发设置',subtitle:'图片、视频独立排队；所有项目共用这两个并发上限。',body:`${concurrencyControl('images','资产图片并发','每个角色、场景或道具占一个任务。')}${concurrencyControl('videos','视频并发','每条分镜占一个任务，完成后自动下载。')}<p class="small-text muted concurrency-note">默认各 10 条，可设置 1～50。保存后排队任务按新上限启动；调低不会中断正在生成的任务。实际速度取决于服务商并发额度。</p>`,footer:'<button data-action="close-modal">取消</button><button class="primary" data-action="save-concurrency">保存并发设置</button>'});}
function syncConcurrency(key,value){const number=document.querySelector(`#concurrency-${key}`),range=document.querySelector(`[data-concurrency-range="${key}"]`);if(!number||!range)return;number.value=value;range.value=value;range.style.setProperty('--range-fill',`${(Number(value)-1)/49*100}%`);}
function openSettings(){openModal({title:'工作台设置',subtitle:'厂商方案、Key与提示词保存在本机，更新时保留。',wide:true,body:`<div class="settings-tabs"><button class="active" data-action="settings-tab" data-tab="api">接口配置</button><button data-action="settings-tab" data-tab="prompts">系统提示词</button><button data-action="settings-tab" data-tab="updates">软件更新 · v${escape(state.updates.version)}</button></div><div data-settings-panel="api">${providerPanel(state.settings,state.providerProfiles)}<div class="hint-box">${escape(state.videoProfile.unavailable?state.videoProfile.error:'模型参数按已保存方案获取，更换型号后可刷新。')} <button data-action="refresh-video-capabilities">刷新已保存的视频方案参数</button></div></div><div data-settings-panel="prompts" hidden>${promptSettingsPanel()}</div><div data-settings-panel="updates" hidden>${updatePanel(state.updates)}</div>`,footer:'<button data-action="close-modal">取消</button><button class="primary" data-action="save-settings" data-settings-save="api">保存接口设置</button><button class="primary" data-action="save-prompts" data-settings-save="prompts" hidden>保存系统提示词</button><button class="primary" data-action="save-updates" data-settings-save="updates" hidden>保存更新设置</button>'});}
function chunksSection(project){if(!project.chunks?.length)return '';return `<section class="section-card chunk-section"><div class="section-top"><div><h2>剧本拆解 <span class="count">${project.chunks.length} 段</span></h2><p class="section-subtitle">逐段保存进度；视频分镜会在页面最下方全部列出，确认后才提交。</p></div></div><div class="chunk-list">${project.chunks.map(chunk=>`<details><summary><span>${String(chunk.index).padStart(2,'0')}　${escape(chunk.title)}</span><span class="muted small-text">${chunk.text.length} 字 · ${chunk.referenceOnly?'参考资料':chunk.storyboardState==='completed'?'分镜已列出':chunk.analysisState==='completed'?'清单已列出':'待分析'}</span></summary><pre>${escape(chunk.text)}</pre></details>`).join('')}</div></section>`;}

function promptSettingsPanel(){const prompts=state.prompts;return `<div class="hint-box">留空使用默认规则，点击“恢复默认”会清空该项，保存后生效。新一轮分析使用当前规则；已经列出的资产和分镜会保留。人物图仍自动附加单张16:9面部＋三视图规则。</div><div class="prompt-settings-layout"><nav class="prompt-nav" aria-label="系统提示词分类">${prompts.definitions.map((item,index)=>`<button class="${index===0?'active':''}" data-action="prompt-category" data-key="${item.key}">${escape(item.label)}</button>`).join('')}</nav><div>${prompts.definitions.map((item,index)=>`<section class="prompt-panel" data-prompt-panel="${item.key}" ${index?'hidden':''}><div class="section-heading"><div><h3>${escape(item.label)}</h3><p>${escape(item.description)}</p></div><button class="small" data-action="reset-prompt" data-key="${item.key}">恢复默认</button></div><label class="field"><span>自定义系统提示词 · ${prompts.overrides[item.key]?'已自定义':'默认'}</span><textarea id="prompt-${item.key}" data-system-prompt="${item.key}" maxlength="20000" placeholder="留空使用默认规则">${escape(prompts.overrides[item.key]||'')}</textarea></label><details class="hint-box character-rule"><summary>查看默认提示词</summary><pre>${escape(item.default)}</pre></details></section>`).join('')}<details class="hint-box character-rule"><summary>固定输出字段与引用规则</summary><pre>${escape(prompts.outputContract)}</pre></details></div></div>`;}

function openLogs(){const project=state.project;openModal({title:'任务记录',subtitle:project?project.title:'创建项目后，这里会记录每一步进度。',wide:true,body:project?.logs.length?`<div class="log-list">${[...project.logs].reverse().map(item=>`<div class="log-item ${item.level}"><time>${new Date(item.at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</time><span class="dot"></span><span>${escape(item.message)}</span></div>`).join('')}</div>`:'<div class="empty-panel"><p>还没有任务记录。</p></div>',footer:'<button data-action="refresh-logs">刷新记录</button><button data-action="close-modal">关闭</button>'});}

async function saveProject(){const project=await api(`/api/projects/${state.project.id}`,{method:'PATCH',body:state.draft});state.dirty=false;setProject(project);await refreshProjects();render();return project;}
async function regenerate(id,resume=false){const project=await api(`/api/projects/${state.project.id}/assets/${id}/generate`,{method:'POST',body:{resume}});setProject(project);notify(resume?'正在继续查询原任务':'已开始重新生成这张图片');}
async function prepare(){state.busy=true;render();try{if(state.dirty)await saveProject();if(state.project.sourceChanged){const project=await api(`/api/projects/${state.project.id}/duplicate`,{method:'POST',body:{skipReview:state.project.skipReview===true}});await refreshProjects();setProject(project,{reset:true});localStorage.setItem('drama-project',project.id);}const project=await api(`/api/projects/${state.project.id}/prepare`,{method:'POST'});setProject(project);notify(project.skipReview?'全自动已开始：依次生成资产、分镜和视频':'正在拆解剧本，仅列清单，不生成图片或视频');}finally{state.busy=false;render();}}

document.addEventListener('input',event=>{if(handleModelListInput(event.target))return;const range=event.target.dataset.concurrencyRange,number=event.target.dataset.concurrencyNumber;if(range){syncConcurrency(range,event.target.value);return;}if(number){const input=document.querySelector(`[data-concurrency-range="${number}"]`);input.value=event.target.value;return;}const field=event.target.dataset.draft;if(field){state.draft[field]=event.target.value;state.dirty=true;const counters=document.querySelectorAll('.editor-bottom span');if(counters[0])counters[0].textContent=state.draft.script.length.toLocaleString()+' 字';if(counters[1])counters[1].textContent='有未保存的修改';const save=document.querySelector('[data-action="save-project"]');if(save){save.disabled=false;save.innerHTML=`${icon('save',14)}<span>保存修改</span>`;}}});
document.addEventListener('change',async event=>{if(event.target.dataset.imageModelSelect!==undefined){const select=event.target,previous=state.settings.grsai.model;select.disabled=true;try{state.settings=await api('/api/settings',{method:'POST',body:{grsai:{model:select.value}}});state.providerProfiles=await api('/api/provider-profiles');render();notify('生图模型已切换为 '+state.settings.grsai.model);}catch(error){select.value=previous;select.disabled=false;notify(error.message,true);}return;}if(handleProviderChange(event.target,state.providerProfiles))return;if(event.target.dataset.shotDuration){const select=event.target,id=select.dataset.shotDuration,previous=state.project.shots.find(shot=>shot.id===id).duration;select.disabled=true;try{setProject(await api(`/api/projects/${state.project.id}/shots/${id}`,{method:'PATCH',body:{duration:Number(select.value)}}));notify('分镜时长已保存；可编辑时间线或点击重新拆分分镜');}catch(error){select.value=previous;select.disabled=false;notify(error.message,true);}return;}motionRequested=false;if(event.target.id==='skip-review'){const enabled=event.target.checked;try{const project=await api(`/api/projects/${state.project.id}`,{method:'PATCH',body:{skipReview:enabled}});state.draft.skipReview=enabled;setProject(project);notify(enabled?'已开启；点击开始后自动生成资产、分镜和视频，会产生费用':'已关闭；已提交的任务继续查询，后续任务等待手动确认');}catch(error){event.target.checked=!enabled;notify(error.message,true);}return;}if(event.target.dataset.assetSelect){const id=event.target.dataset.assetSelect;event.target.checked?state.selectedAssets.add(id):state.selectedAssets.delete(id);syncSelections();}if(event.target.id==='select-all-assets'){state.selectedAssets=new Set(event.target.checked?state.project.assets.map(asset=>asset.id):[]);syncSelections();}if(event.target.dataset.shotSelect){const id=event.target.dataset.shotSelect;event.target.checked?state.selected.add(id):state.selected.delete(id);syncSelections();}if(event.target.id==='select-all'){state.selected=new Set(event.target.checked?state.project.shots.filter(shot=>!active(shot.job)).map(shot=>shot.id):[]);syncSelections();}});
document.addEventListener('keydown',event=>{if(imageViewerOpen())return;if((event.key==='Enter'||event.key===' ')&&event.target.matches('[data-zoom-image]')){event.preventDefault();openImageViewer(event.target);return;}if(!state.modal)return;if(event.key==='Escape'){closeModal();return;}if(event.key==='Tab'){const focusable=[...document.querySelectorAll('.modal button:not(:disabled),.modal input:not(:disabled),.modal textarea,.modal select,.modal a')].filter(element=>element.offsetParent!==null);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});

document.addEventListener('click',async event=>{
  if(imageViewerOpen()||event.target.closest('.image-lightbox'))return;
  const picture=event.target.closest('[data-zoom-image]');if(picture){openImageViewer(picture);return;}
  const button=event.target.closest('[data-action]');if(!button||button.disabled)return;
  const action=button.dataset.action,id=button.dataset.id;motionRequested=true;
  try{
    if(action==='concurrency')return await openConcurrency();
    if(action==='concurrency-step'||action==='concurrency-preset'){const key=button.dataset.key;const old=Number(document.querySelector(`#concurrency-${key}`).value)||10;syncConcurrency(key,Math.max(1,Math.min(50,action==='concurrency-preset'?Number(button.dataset.value):old+Number(button.dataset.step))));return;}
    if(action==='save-concurrency'){const images=Number(document.querySelector('#concurrency-images').value),videos=Number(document.querySelector('#concurrency-videos').value);if(![images,videos].every(n=>Number.isInteger(n)&&n>=1&&n<=50))throw new Error('请输入1～50之间的整数');modalBusy(true);state.concurrency=await api('/api/concurrency',{method:'POST',body:{images,videos}});modalBusy(false);closeModal();render();notify(`并发已保存：图片 ${images} 条，视频 ${videos} 条`);return;}
    if(action==='new')return openNew();
    if(action==='close-modal')return closeModal();
    if(action==='project'){if(state.dirty){await saveProject();}return await loadProject(id);}
    if(action==='create-project'){modalBusy(true);const title=document.querySelector('#new-title').value.trim()||'未命名短剧';const project=await api('/api/projects',{method:'POST',body:{title}});modalBusy(false);closeModal();await refreshProjects();setProject(project,{reset:true});localStorage.setItem('drama-project',project.id);document.querySelector('#script-input')?.focus();return;}
    if(action==='filter'){state.filter=button.dataset.kind;return render();}
    if(action==='save-project'){await saveProject();notify('剧本和制作设置已保存');return;}
    if(action==='prepare')return await prepare();
    if(action==='rename'){openModal({title:'修改项目名称',body:`<label class="field"><span>项目名称</span><input id="rename-title" value="${escape(state.project.title)}" maxlength="80"></label>`,footer:'<button data-action="close-modal">取消</button><button class="primary" data-action="save-name">保存</button>'});return;}
    if(action==='save-name'){state.draft.title=document.querySelector('#rename-title').value;await saveProject();closeModal();notify('项目名称已更新');return;}
    if(action==='duplicate'){if(state.dirty)await saveProject();const project=await api(`/api/projects/${state.project.id}/duplicate`,{method:'POST',body:{skipReview:state.project.skipReview===true}});await refreshProjects();setProject(project,{reset:true});localStorage.setItem('drama-project',project.id);notify('已创建新版本，原有素材与成片保留');return;}
    if(action==='edit-asset')return editAsset(id);
    if(action==='regenerate-asset')return editAsset(id);
    if(action==='resume-asset')return await regenerate(id,true);
    if(action==='upload-asset'){uploadAssetId=id;document.querySelector('#asset-file').value='';document.querySelector('#asset-file').click();return;}
    if(action==='save-asset'||action==='save-regenerate-asset'){modalBusy(true);const project=await api(`/api/projects/${state.project.id}/assets/${id}`,{method:'PATCH',body:{name:document.querySelector('#asset-name').value,description:document.querySelector('#asset-description').value,prompt:document.querySelector('#asset-prompt').value}});setProject(project);modalBusy(false);closeModal();if(action==='save-regenerate-asset')await regenerate(id);else notify('素材设定已保存');return;}
    if(action==='edit-shot')return editShot(id);
    if(action==='preview-reference'){openImageViewer(button.querySelector('img'));return;}
    if(action==='reparse-storyboards'){if(state.dirty)await saveProject();return reparseStoryboardsDialog();}
    if(action==='confirm-reparse-storyboards'||action==='resume-reparse-storyboards'){const body=action==='resume-reparse-storyboards'?{resume:true}:{duration:Number(document.querySelector('#reparse-duration').value),notes:document.querySelector('#reparse-notes').value};modalBusy(true);const project=await api(`/api/projects/${state.project.id}/reparse-storyboards`,{method:'POST',body});modalBusy(false);closeModal();setProject(project);notify('开始全部重新解析，复用资产图片；完成后仍等待你确认视频');return;}
    if(action==='rebuild-shot')return rebuildShotDialog(id);
    if(action==='confirm-rebuild-shot'){const draft=state.modal.rebuildDraft;modalBusy(true);const project=await api(`/api/projects/${state.project.id}/shots/${id}/rebuild`,{method:'POST',body:{title:draft.title,prompt:document.querySelector('#rebuild-prompt').value,duration:Number(document.querySelector('#rebuild-duration').value),notes:document.querySelector('#rebuild-notes').value}});modalBusy(false);closeModal();setProject(project);notify('AI开始重新拆分，完成后仍由你确认视频');return;}
    if(action==='save-shot'){modalBusy(true);const project=await api(`/api/projects/${state.project.id}/shots/${id}`,{method:'PATCH',body:{title:document.querySelector('#shot-title').value,prompt:document.querySelector('#shot-prompt').value,duration:Number(document.querySelector('#shot-duration').value)}});modalBusy(false);closeModal();setProject(project);notify('分镜提示词已保存');return;}
    if(action==='review-shot')return await openReview([id]);
    if(action==='review-selected')return await openReview([...state.selected]);
    if(action==='confirm-video'){const review=state.modal.review;modalBusy(true);const project=await api(`/api/projects/${review.projectId}/videos`,{method:'POST',body:{shotIds:review.shots.map(shot=>shot.id),approvedHash:review.hash}});modalBusy(false);closeModal();state.selected.clear();setProject(project);notify('视频已加入后台队列，完成后会自动下载');return;}
    if(action==='resume-video'){setProject(await api(`/api/projects/${state.project.id}/shots/${id}/resume`,{method:'POST'}));notify('正在继续查询原视频任务');return;}
    if(action==='play'){const shot=state.project.shots.find(item=>item.id===id);openModal({title:shot.title,subtitle:'已生成的视频 · 原始下载文件',wide:true,body:`<video class="player" controls autoplay playsinline src="${shot.video.url}"></video>`,footer:`<a href="${shot.video.url}" download="${escape(state.project.title)}.mp4"><button>${icon('download',14)}下载视频</button></a><button data-action="close-modal">关闭</button>`});return;}
    if(action==='merge'){setProject(await api(`/api/projects/${state.project.id}/merge`,{method:'POST'}));notify('开始在本机合成整集，原始片段会保留');return;}
    if(action==='play-merged'){const video=state.project.mergedVideo;openModal({title:`${state.project.title} · 整集`,subtitle:`包含 ${video.clips} 个片段 · 约 ${Number(video.duration).toFixed(1)} 秒`,wide:true,body:`<video class="player" controls autoplay playsinline src="${video.url}"></video>`,footer:`<a href="${video.url}" download="${escape(state.project.title)}_整集.mp4"><button>${icon('download',14)}下载整集</button></a><button data-action="close-modal">关闭</button>`});return;}
    if(action==='generate-selected-assets'||action==='generate-all-assets'){
      if(state.dirty)await saveProject();
      const assetIds=action==='generate-all-assets'?state.project.assets.map(asset=>asset.id):[...state.selectedAssets];
      state.selectedAssets=new Set(assetIds);setProject(await api(`/api/projects/${state.project.id}/generate-assets`,{method:'POST',body:{assetIds}}));
      notify(state.project.skipReview?'正在生成所选资产，分镜全部列出后自动生成视频':'开始生成选中的资产；随后列出全部分镜，视频仍等待你确认');return;
    }
    if(action==='settings-tab'){
      const tab=button.dataset.tab;
      document.querySelectorAll('[data-settings-panel]').forEach(node=>node.hidden=node.dataset.settingsPanel!==tab);
      document.querySelectorAll('[data-settings-save]').forEach(node=>node.hidden=node.dataset.settingsSave!==tab);
      document.querySelectorAll('[data-action="settings-tab"]').forEach(node=>node.classList.toggle('active',node.dataset.tab===tab));movePill(button.parentElement);document.querySelectorAll(`[data-settings-panel="${tab}"] .prompt-nav`).forEach(movePill);if(!reducedMotion())slidePanels(document.querySelector(`[data-settings-panel="${tab}"]`));return;
    }
    if(action==='prompt-category'){
      document.querySelectorAll('[data-prompt-panel]').forEach(node=>node.hidden=node.dataset.promptPanel!==button.dataset.key);
      document.querySelectorAll('[data-action="prompt-category"]').forEach(node=>node.classList.toggle('active',node.dataset.key===button.dataset.key));movePill(button.parentElement);if(!reducedMotion())slidePanels(document.querySelector(`[data-prompt-panel="${button.dataset.key}"]`));return;
    }
    if(action==='reset-prompt'){document.querySelector(`#prompt-${button.dataset.key}`).value='';return;}
    if(action==='save-prompts'){
      const body=Object.fromEntries([...document.querySelectorAll('[data-system-prompt]')].map(node=>[node.dataset.systemPrompt,node.value]));
      modalBusy(true);state.prompts=await api('/api/prompts',{method:'POST',body});modalBusy(false);closeModal();notify('系统提示词已保存，留空项使用默认规则');return;
    }
    if(action==='settings')return openSettings();
    if(action==='save-settings'){const settings=collectProviders();modalBusy(true);state.settings=await api('/api/settings',{method:'POST',body:settings});state.providerProfiles=await api('/api/provider-profiles');const bootstrap=await api('/api/bootstrap');state.videoProfile=bootstrap.videoProfile;modalBusy(false);closeModal();if(state.project)await loadProject(state.project.id);else render();notify('厂商方案已保存，原有Key与任务配置保留');return;}
    if(['save-updates','check-update','install-update'].includes(action)){modalBusy(true);if(action!=='install-update')state.updates=await api('/api/updates/settings',{method:'POST',body:collectUpdateSettings()});if(action!=='save-updates')state.updates=await api('/api/updates/'+(action==='check-update'?'check':'install'),{method:'POST'});modalBusy(false);document.querySelector('[data-settings-panel="updates"]').innerHTML=updatePanel(state.updates);notify(state.updates.message||'更新设置已保存',state.updates.state==='error');if(state.updates.state==='installed')reconnectAfterUpdate();return;}
    if(action==='confirm-continuity'){setProject(await api(`/api/projects/${state.project.id}/shots/${id}/confirm-continuity`,{method:'POST'}));notify('该分镜衔接已确认');return;}
    if(action==='refresh-video-capabilities'){modalBusy(true);state.capabilities=await api('/api/capabilities');const boot=await api('/api/bootstrap');state.videoProfile=boot.videoProfile;modalBusy(false);notify(state.videoProfile.unavailable?state.videoProfile.error:'视频参数已刷新',state.videoProfile.unavailable);return;}
    if(action==='logs')return openLogs();
    if(action==='refresh-logs'){if(state.project)state.project=await api(`/api/projects/${state.project.id}`);return openLogs();}
  }catch(error){modalBusy(false);if(state.modal)modalError(error);else notify(error.message,true);}
});

document.querySelector('#asset-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file||!uploadAssetId)return;if(file.size>15*1024*1024)return notify('请选择15MB以内的图片',true);try{const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));const project=await api(`/api/projects/${state.project.id}/assets/${uploadAssetId}/image`,{method:'POST',body:{base64:btoa(binary)}});setProject(project);notify('图片已替换，相关分镜需要重新确认');}catch(error){notify(error.message,true);}});

async function poll(){if(polling||switching)return;polling=true;try{await refreshProjects();if(state.project){const id=state.project.id,project=await api(`/api/projects/${id}`);if(state.project?.id!==id)return;const json=JSON.stringify(project);if(json!==lastProjectJSON||state.disconnected){state.disconnected=false;setProject(project);}}else if(state.disconnected){state.disconnected=false;render();}}catch{if(!state.disconnected){state.disconnected=true;render();}}finally{polling=false;}}
let reconnecting=false;
async function reconnectAfterUpdate(){if(reconnecting)return;reconnecting=true;notify('更新完成，正在重启并重新连接…');for(let i=0;i<30;i++){await new Promise(r=>setTimeout(r,1000));try{const next=await api('/api/bootstrap');if(next.updates.version!==state.updates.version){location.reload();return;}}catch{}}reconnecting=false;notify('请刷新页面或重新双击启动工作台',true);}
async function pollUpdates(){try{const update=await api('/api/updates');if(update.version!==state.updates.version){location.reload();return;}state.updates=update;if(update.state==='installed')reconnectAfterUpdate();const panel=document.querySelector('[data-settings-panel="updates"]');if(panel&&!panel.hidden){const status=panel.querySelector('#update-status');if(status)status.textContent=update.message||'';const button=panel.querySelector('[data-action="install-update"]');if(button)button.disabled=!['available','waiting'].includes(update.state);}}catch{}}
async function boot(){try{const bootstrap=await api('/api/bootstrap');Object.assign(state,{token:bootstrap.token,settings:bootstrap.settings,providerProfiles:bootstrap.providerProfiles,updates:bootstrap.updates,projects:bootstrap.projects,capabilities:bootstrap.capabilities,concurrency:bootstrap.concurrency,videoProfile:bootstrap.videoProfile,prompts:bootstrap.prompts,rules:bootstrap.rules||{}});const saved=localStorage.getItem('drama-project');const id=state.projects.find(project=>project.id===saved)?.id||state.projects[0]?.id;if(id)await loadProject(id);else render();setInterval(poll,2000);setInterval(pollUpdates,15000);}catch(error){document.querySelector('#app').innerHTML=`<div class="initial-loading"><span class="brand-mark">镜</span><p>工作台暂时无法连接</p><p class="small-text">${escape(error.message)}</p><button onclick="location.reload()">重新连接</button></div>`;}}
await boot();
